// Teklifbul Rule v1.0 - Binary type aliases for Excel operations
// Excel okuma/yazma gibi yerlerde kullanabileceğimiz daha anlamlı bir alias

declare type BinaryLike = Buffer | ArrayBuffer | Uint8Array;

// Excel okuma/yazma gibi yerlerde kullanabileceğimiz daha anlamlı bir alias:
declare type ExcelBinary = BinaryLike;

